// Source-linked breadth. Reading advice is editorial, never an author endorsement.
const checked='2026-10-11', works=[];
const paid={access:'Institutional / purchase access',accessNote:'Publisher access requires purchase or an eligible library subscription. Free front matter, sample chapters and previews are not the complete book.'};
function add(topic,title,author,level,url,version,note,prerequisites,extra={}){works.push({bucket:'Subject depth expansion',topic,title,author,level,url,source:url,kind:'Textbook',language:'English',version,note,prerequisites:'Editorial preparation: '+prerequisites,use:level==='Introductory'?'Work through examples and exercises before advancing.':level==='Intermediate'?'Develop proof-based undergraduate tools; compare the subject reading guide.':'Study selectively after the stated foundations; use the subject guide to choose a specialization.',checked,...extra})}
function s(topic,title,author,level,doi,version,note,prep){add(topic,title,author,level,'https://link.springer.com/book/'+doi,version,note,prep,paid)}
function aim(topic,title,author,level,slug,version,note,prep){add(topic,title,author,level,'https://textbooks.aimath.org/textbooks/approved-textbooks/'+slug+'/',version,note,prep,{access:'Official page — verify access',accessNote:'AIM lists an authorized open edition and its author/download route. This link is a source page, not a direct PDF; follow its full-text link and observe the stated licence.'})}
aim('proofs','Mathematical Discovery','Andrew M. Bruckner, Brian S. Thomson and Judith B. Bruckner','Introductory','btb-md','Author edition listed by AIM; consult its title page','An inquiry-based route from patterns and conjectures to justification. Read it for active exploration rather than as a catalogue of proof templates.','School algebra; willingness to solve exploratory problems.');
aim('logic','A Friendly Introduction to Mathematical Logic','Christopher C. Leary and Lars Kristiansen','Intermediate','leary-kristiansen','Second edition, 2015','Connects formal syntax, semantics and computability, with a route to incompleteness. A next step after learning to write mathematical proofs.','Proof-writing; sets and functions.');
aim('calculus','Calculus in Context','James Callahan, Kenneth Hoffman, David Cox, Donal O’Shea, Harriet Pollatsek and Lester Senechal','Introductory','callahan','Original 1995; authorized online edition','Develops calculus through scientific models and dynamical systems. Useful alongside a more proof-focused treatment, not a substitute for real analysis.','Precalculus, functions and graphs.');
aim('calculus','Calculus I–III','Jerrold E. Marsden and Alan Weinstein','Introductory','marsden-weinstein','Springer 1985; authorized PDFs; three-volume sequence counted once','A single- and multivariable sequence with geometric motivation and exercises. The full sequence is one work here, not three inflated entries.','Precalculus and elementary coordinate geometry.');
aim('calculus','Vector Calculus','Michael Corral','Intermediate','corral','Author-maintained edition; consult source for revision','Focuses on several variables and vector calculus. Use it to consolidate line/surface integration and the geometric meaning of the integral theorems.','Single-variable differentiation and integration; vectors.');
aim('real-analysis','Elementary Real Analysis','Brian S. Thomson, Judith B. Bruckner and Andrew M. Bruckner','Intermediate','thomson-bruckner-bruckner','Second authorized edition; original 2001','A sustained undergraduate treatment with exercises. Screen and print versions are the same work, and the split volumes are not counted separately.','Calculus; introductory proof-writing.');
aim('real-analysis','Mathematical Analysis I','Elias Zakon','Intermediate','zakon','Trillia edition, 2004; based on earlier course notes','Builds analysis systematically from set-theoretic and metric ideas. An alternative route for readers wanting a longer foundational development.','Calculus; elementary set language.');
aim('real-analysis','How We Got from There to Here: A Story of Real Analysis','Robert Rogers and Eugene Boman','Intermediate','rogers-boman','Milne Open Textbooks edition; consult source','Introduces rigorous analysis through its historical problems. Many arguments are developed through reader exercises, so this is an active-reading companion.','Calculus; elementary proof techniques.');
aim('complex-analysis','A First Course in Complex Analysis','Matthias Beck, Gerald Marchesi, Dennis Pixton and Lucas Sabalka','Intermediate','beck-marchesi-pixton-sabalka','Author-maintained open edition','A concise first course in holomorphic functions and contour methods. Work exercises before moving to several complex variables.','Multivariable calculus; real-analysis basics.');
aim('complex-analysis','Complex Analysis','Russell Howell and John Mathews','Intermediate','howell','Authorized open edition after six commercial editions','A first complex-analysis course with many exercises and geometric explanations. Suitable as a computational and conceptual complement to a proof-intensive text.','Calculus; complex arithmetic.');
aim('combinatorics','Combinatorics Through Guided Discovery','Kenneth P. Bogart','Introductory','bogart','2004; authorized online/PDF editions','Problems guide the development of counting and graph ideas. Use it to practice discovering and proving arguments, rather than reading solutions first.','Proof-writing; elementary counting.');
aim('combinatorics','Counting Rocks! An Introduction to Combinatorics','Henry Adams, Kelly Emmrich, Maria Gillespie, Shannon Golden and Rachel Pries','Introductory','coloradostate','January 2023 version listed by AIM','A first combinatorics course accompanied by course videos. Counting methods and graph examples offer a bridge into more abstract enumerative texts.','Elementary discrete mathematics.');
aim('combinatorics','Foundations of Combinatorics with Applications','Edward A. Bender and S. Gill Williamson','Intermediate','bender-williamson','Authorized 2006 edition','Combines enumerative and graph-theoretic tools with algorithmic applications. The source distributes the text in multiple PDF files, counted as one book.','Proof-writing; elementary algorithms.');
aim('differential-equations','Elementary Differential Equations with Boundary Value Problems','William F. Trench','Intermediate','trench-de','Authorized online edition; original commercial text','A lengthy first differential-equations course with boundary-value material. The shorter edition and expanded edition are not counted as separate works.','Single-variable calculus and elementary linear algebra.');
aim('differential-equations','The Ordinary Differential Equations Project','Thomas Judson','Intermediate','judson-odes','Author-maintained PreTeXt edition','Combines ODE theory, models, computation and projects. Optional computational activities do not replace the proof-based preparation needed for graduate PDE.','Calculus; linear algebra.');
s('real-analysis','Understanding Analysis','Stephen Abbott','Intermediate','10.1007/978-0-387-21506-8','First edition, 2001','A one-semester bridge from calculus to rigorous analysis, built around the phenomena that make limiting arguments necessary.','Calculus and proof-writing.');
s('linear-algebra','Advanced Linear Algebra','Steven Roman','Graduate','10.1007/0-387-27474-X','Second edition, 2005','Develops structural linear algebra beyond matrix manipulation, including module-theoretic viewpoints and additional advanced topics.','A proof-based linear-algebra course; rings and modules helpful.');
add('linear-algebra','Matrix Analysis','Roger A. Horn and Charles R. Johnson','Graduate','https://www.cambridge.org/highereducation/books/matrix-analysis/FDA3627DC2B9F5C3DF2FD8C3CC136B48','Second edition; publisher release 2012, imprint 2013','An extensive second course covering canonical forms, matrix norms, positivity and spectral questions. Its many problems are useful for mastering matrix arguments.','Proof-based linear algebra; some real/complex analysis.',paid);
s('linear-algebra','Matrix Analysis','Rajendra Bhatia','Graduate','10.1007/978-1-4612-0653-8','1997','Studies matrix inequalities and spectral structure from an analytic viewpoint. Distinct from the Horn–Johnson book with the same title.','Linear algebra, norms and elementary analysis.');
s('abstract-algebra','Algebra','Thomas W. Hungerford','Graduate','10.1007/978-1-4612-6101-8','1974','A broad graduate algebra text emphasizing groups, rings, modules and fields. Use selected parts after a first abstract-algebra course.','Undergraduate algebra and proof-writing.');
s('abstract-algebra','Exercises in Classical Ring Theory','T. Y. Lam','Graduate','10.1007/b97448','Second edition, 2003','A problem-based companion for noncommutative ring theory: semisimple rings, radicals, division rings and related constructions.','Rings, modules and a first graduate algebra course.');
s('abstract-algebra','Glimpses of Algebra and Geometry','Gábor Tóth','Intermediate','10.1007/b98964','Second edition, 2002','Connects classical geometry and number-theoretic examples with algebra. A bridge between introductory courses and structural graduate algebra.','Linear algebra and basic abstract algebra.');
s('commutative-algebra','Commutative Algebra I','Oscar Zariski and Pierre Samuel','Graduate','9780387900896','Springer reprint, 1975; original volume 1958','A classical development of commutative algebra, with a detailed algebraic style. Historical notation should be compared with a modern scheme-oriented course.','Groups, rings, fields and modules.');
s('commutative-algebra','(Mostly) Commutative Algebra','Antoine Chambert-Loir','Graduate','10.1007/978-3-030-61595-6','2021','A course-based introduction with algebraic examples and exercises. Useful for consolidating the passage from undergraduate algebra to geometry.','Abstract algebra; linear algebra.');
s('commutative-algebra','Computational Linear and Commutative Algebra','Martin Kreuzer and Lorenzo Robbiano','Graduate','10.1007/978-3-319-43601-2','2016','Connects commuting matrices, zero-dimensional rings and polynomial-system methods. A computational specialization, not another general first course.','Linear algebra; commutative rings and polynomial ideals.');
s('category-theory','An Introduction to the Language of Category Theory','Steven Roman','Intermediate','10.1007/978-3-319-41917-6','2017','A compact route through functors, natural transformations, limits and adjunctions. Use concrete algebraic examples before studying higher categorical models.','Proof-based algebra; sets and functions.');
s('representation-theory','Introduction to Lie Algebras and Representation Theory','James E. Humphreys','Graduate','10.1007/978-1-4612-6398-2','1972','Develops semisimple Lie algebras and their representations in characteristic zero. Roots and weights require familiarity with bilinear algebra.','Linear algebra; abstract algebra.');
s('representation-theory','Introduction to Lie Algebras','Karin Erdmann and Mark J. Wildon','Intermediate','10.1007/1-84628-490-2','2006','An entry route emphasizing examples and exercises before the full machinery of semisimple Lie theory.','Proof-based linear algebra.');
s('representation-theory','Lie Groups, Lie Algebras, and Representations: An Elementary Introduction','Brian C. Hall','Graduate','10.1007/978-0-387-21554-9','First edition, 2003','Uses matrix groups to relate group geometry and infinitesimal structure. Start here before more general structural Lie-group references.','Linear algebra; advanced calculus.');
s('representation-theory','Symmetry, Representations, and Invariants','Roe Goodman and Nolan R. Wallach','Graduate','10.1007/978-0-387-79852-3','2009','A substantial reference connecting classical groups, highest weights and invariant theory. Select chapters according to the intended representation-theoretic problem.','Lie algebras; tensor algebra; basic algebraic groups.');
s('representation-theory','Lie Groups Beyond an Introduction','Anthony W. Knapp','Graduate','10.1007/978-1-4757-2453-0','First edition, 1996','Studies structural Lie theory beyond matrix-group introductions. Use after gaining confidence with Lie algebras and root systems.','Lie groups and Lie algebras; smooth manifolds.');
s('set-theory','Set Theory: An Introduction','Robert L. Vaught','Intermediate','9780817642563','2001 reprint','A compact progression from sets, ordinals and cardinals toward axiomatic considerations. Good for preparing to understand consistency questions.','Proof-writing; elementary logic.');
s('set-theory','Combinatorial Set Theory: With a Gentle Introduction to Forcing','Lorenz J. Halbeisen','Graduate','10.1007/978-3-031-91752-3','Third edition, 2025','Develops combinatorial set theory, choice principles and forcing. Follow the foundational chapters before selecting a specialized continuum problem.','Axiomatic set theory and first-order logic.');
s('model-theory','Model Theory: The Algebraic Basics','Davide Rizza','Intermediate','10.1007/978-3-032-03796-1','2025','A gradual introduction emphasizing algebraic structures, quantifier elimination and types. A bridge for readers with a limited prior logic background.','Proof-writing; elementary sets and algebra.');
s('model-theory','A Course on Basic Model Theory','Haimanti Sarbadhikari and Shashi Mohan Srivastava','Graduate','10.1007/978-981-10-5098-5','2017','Develops central model-theoretic ideas with supporting logic and set-theoretic preparation. Read alongside exercises in structures and types.','First-order logic and proof-writing.');
s('measure-theory','Measure Theory and Probability Theory','Krishna B. Athreya and Soumendra N. Lahiri','Graduate','10.1007/978-0-387-35434-7','2006','Builds measure-theoretic foundations with probability as a guiding application. This is a full text, not a single probability chapter counted separately.','Real analysis; basic probability helpful.');
s('measure-theory','Measure Theory, Probability, and Stochastic Processes','Jean-François Le Gall','Graduate','10.1007/978-3-031-14205-5','2022','Moves from measure and integration to martingales, Markov chains and Brownian motion. A route linking analysis and probabilistic processes.','Real analysis; elementary probability.');
s('functional-analysis','Functional Analysis','S. Kesavan','Graduate','10.1007/978-981-19-7633-9','Second edition, 2023','Develops the functional-analytic toolkit with differential-equation and variational applications. Practice duality and weak-convergence arguments before applications.','Real analysis; measure theory; normed spaces.');
s('functional-analysis','Functional Analysis: Fundamentals and Applications','Michel Willem','Graduate','10.1007/978-3-031-09149-0','Second edition, 2022','Relates Lebesgue, dual and Sobolev spaces to capacity and elliptic problems. A functional route into variational PDE tools.','Real analysis and integration.');
s('functional-analysis','Functional Analysis','Erdoğan S. Şuhubi','Graduate','10.1007/978-94-017-0141-9','2003','A long treatment of infinite-dimensional spaces and operators. Use as a supporting reference when a shorter course leaves gaps.','Real analysis; metric spaces; linear algebra.');
s('functional-analysis','Linear Functional Analysis','Bryan Patrick Rynne and Martin Alexander Youngson','Intermediate','10.1007/978-1-4471-3655-2','First edition, 2000','An entry course in normed-space and operator methods. Suitable before advanced spectral theory or nonlinear analysis.','Proof-based analysis and linear algebra.');
s('complex-analysis','Complex Analysis','Joseph Bak and Donald J. Newman','Intermediate','10.1007/978-1-4419-7288-0','Third edition, 2010','A first complex-variable course connecting contour methods, analytic continuation and classical applications.','Real analysis and multivariable calculus.');
s('complex-analysis','Complex Analysis: In the Spirit of Lipman Bers','Jane P. Gilman, Irwin Kra and Rubí E. Rodríguez','Graduate','10.1007/978-0-387-74715-6','First edition, 2007','Develops classical complex analysis with a geometric perspective. Useful before studying Riemann surfaces or complex geometry.','Real analysis; a first complex-analysis course helpful.');
s('complex-analysis','Complex Analysis','Serge Lang','Graduate','10.1007/978-1-4757-3083-8','Fourth edition, 1999','A compact advanced undergraduate/graduate development with optional specialized material. A different pace from computational introductory texts.','Proof-based real analysis and calculus.');
s('complex-analysis','Complex Analysis','Eberhard Freitag and Rolf Busam','Graduate','10.1007/978-3-540-93983-2','Second edition, 2009','Extends classical complex analysis toward elliptic functions, modular functions and analytic number theory. Sheaf-theoretic methods are not its focus.','Real analysis; basic algebra; elementary complex analysis.');
// Core and specialist references: editions and publisher previews count once.
s('proofs','Proofs and Fundamentals: A First Course in Abstract Mathematics','Ethan D. Bloch','Introductory','10.1007/978-1-4419-7127-2','Second edition, 2011','A transition course on mathematical reasoning, sets and functions. Use the exercises to learn how definitions drive proofs.','School algebra; elementary functions.');
add('proofs','How to Think Like a Mathematician','Kevin Houston','Introductory','https://www.cambridge.org/core/books/how-to-think-like-a-mathematician/FB0813C3AEDDECD40BE58AF186370D52','2009; publisher online edition 2012','Discusses mathematical reading, writing, proof construction and problem solving. A companion to first proof-based courses, not a substitute for solving their exercises.','School mathematics.',paid);
add('proofs','Proof and the Art of Mathematics','Joel David Hamkins','Introductory','https://mitpress.mit.edu/9780262539791/proof-and-the-art-of-mathematics/','2020','Uses accessible mathematical problems to develop proof technique and mathematical judgement. The later examples-and-extensions companion is not counted as another edition of this book.','School algebra and willingness to work on unfamiliar problems.',paid);
s('proofs','Proofs from THE BOOK','Martin Aigner and Günter M. Ziegler','Intermediate','10.1007/978-3-662-57265-8','Sixth edition, 2018','A collection of elegant arguments across several fields. Read after learning basic proof techniques; it is not a systematic first curriculum.','Proof-writing; elementary algebra and combinatorics.');
add('proofs','How to Read and Do Proofs','Daniel Solow','Introductory','https://bcs.wiley.com/he-bcs/Books?action=index&bcsId=2140&itemId=0471680583&itemTypeId=BKS','Fourth-edition companion site; consult publisher for later editions','Organizes proof construction into explicit reasoning strategies. The official companion offers supporting material, not the complete textbook.','School algebra; introductory sets.',paid);
s('logic','Mathematical Logic','Heinz-Dieter Ebbinghaus, Jörg Flum and Wolfgang Thomas','Graduate','10.1007/978-3-030-73839-6','Updated edition, 2021','A systematic first-order-logic course on semantics, completeness, computability and limits of formal methods. Work with examples of structures as well as formal deductions.','Proof-writing; sets and functions.');
s('logic','A Course on Mathematical Logic','Shashi Mohan Srivastava','Intermediate','10.1007/978-0-387-76277-7','2008','A concise path through first-order logic and completeness/incompleteness. Suitable for consolidating formal syntax and semantics before model theory.','Proof-writing; elementary set theory.');
s('logic','A Course in Mathematical Logic for Mathematicians','Yuri I. Manin','Graduate','10.1007/978-1-4419-0615-1','Second edition, 2010','Links foundations with computability and mathematical structures, including a categorical perspective. A mathematically mature alternative to a first introductory course.','First-order logic; algebra and mathematical maturity.');
s('logic','Mathematical Logic: On Numbers, Sets, Structures, and Symmetry','Roman Kossak','Intermediate','10.1007/978-3-031-56215-0','Second edition, 2024','Develops logical ideas through mathematical structures and definability. Use it as an entry into the interaction between logic and algebra.','Proof-writing; basic algebra.');
s('logic','Logic: a Brief Course','Daniele Mundici','Intermediate','10.1007/978-88-470-2361-1','2012','A compact logical course for readers wanting a focused introduction before longer treatments. Compare formal arguments with ordinary mathematical reasoning.','Proof-writing; elementary sets.');
s('logic','Higher-Order Computability','John Longley and Dag Normann','Research','10.1007/978-3-662-47992-6','2015','Studies computation with functionals and higher-type operations. It is a specialist continuation of computability, not an introductory programming book.','Computability theory; mathematical logic; higher-type functionals.');
s('set-theory','The Higher Infinite: Large Cardinals in Set Theory from Their Beginnings','Akihiro Kanamori','Research','10.1007/978-3-540-88867-3','Second edition, 2003','A detailed development of large-cardinal principles and their relationships. Use after axiomatic set theory and introductory forcing.','ZFC, ordinals, cardinals, elementary embeddings and forcing.');
s('set-theory','Axiomatic Set Theory','Gaisi Takeuti and Wilson M. Zaring','Graduate','10.1007/978-1-4684-8751-0','1973','Studies model-construction methods including constructibility, forcing and Boolean-valued models. Historical notation is best compared with a current course.','Axiomatic set theory; first-order logic.');
s('set-theory','Lectures in Set Theory: With Particular Emphasis on the Method of Forcing','Thomas J. Jech','Graduate','10.1007/BFb0061131','Lecture Notes in Mathematics 217, 1971','A short, concentrated course on forcing and consistency methods. Distinct from Jech’s later comprehensive Set Theory reference.','ZFC, ordinals and cardinals; models of first-order theories.');
add('model-theory','Model Theory and Modules','Mike Prest','Research','https://www.cambridge.org/core/books/model-theory-and-modules/EB21CAF6258D4E94D4440A34A5C37D28','1988','Connects model theory with modules, including algebraic structure and definability. Read after a basic model-theory course and module theory.','First-order model theory; rings and modules.',paid);
add('model-theory','Geometric Stability Theory','Anand Pillay','Research','https://academic.oup.com/book/54461','1996','Studies stability through geometric structure, dimension and independence. It is a specialist continuation, not a first introduction to logical syntax.','Model theory, types and stability.',paid);
add('model-theory','Model Theory','C. C. Chang and H. Jerome Keisler','Graduate','https://shop.elsevier.com/books/model-theory/unknown/978-0-444-88054-3','Third edition, 1990','A broad classical reference on structures, elementary equivalence and model constructions. Compare its notation and organization with a modern introductory course.','First-order logic and set theory.',paid);
s('commutative-algebra','The Geometry of Syzygies','David Eisenbud','Research','10.1007/b137572','2005','A second course connecting graded resolutions and projective geometry. Read after commutative algebra and a first algebraic-geometry course.','Graded rings, free resolutions and projective algebraic geometry.');
add('commutative-algebra','Cohen–Macaulay Rings','Winfried Bruns and Jürgen Herzog','Research','https://www.cambridge.org/core/books/cohen-macaulay-rings/938BC2204D8A7C99E2CEBA1695A692A4','Revised edition, 1998','A specialized reference on depth, dimension, canonical modules and related homological structure. Use after a first graduate commutative-algebra course.','Local rings; modules; Ext and Tor.',paid);
add('commutative-algebra','Introduction to Commutative Algebra','Michael F. Atiyah and Ian G. Macdonald','Graduate','https://www.routledge.com/Introduction-To-Commutative-Algebra/Atiyah-MacDonald/p/book/9780367091286','Original 1969; publisher reprint','A concise course in localization, integrality, Noetherian rings and dimension. Exercises carry important parts of the development.','A first abstract-algebra course; modules.',paid);
s('homological-algebra','Methods of Homological Algebra','Sergei I. Gelfand and Yuri I. Manin','Graduate','10.1007/978-3-662-12492-5','Second edition, 2003','Develops classical and derived methods together. Use its categorical perspective after practicing chain complexes and derived functors concretely.','Algebra; modules; category theory.');
s('homological-algebra','Homology','Saunders Mac Lane','Graduate','10.1007/978-3-642-62029-4','1995 reprint; original 1963','A classical homological-algebra reference for complexes, resolutions and derived functors. Compare historical terminology with modern treatments.','Rings, modules and elementary category theory.');
s('homological-algebra','An Introduction to Homological Algebra','Joseph J. Rotman','Graduate','10.1007/b98977','Second edition, 2009','An extensive course with examples and connections to commutative algebra and topology. Distinct from Weibel’s book with the same title.','Abstract algebra, modules and category language.');
add('homological-algebra','An Introduction to Homological Algebra','Charles A. Weibel','Graduate','https://www.cambridge.org/core/books/an-introduction-to-homological-algebra/6DC551295AFCED6F876C0E3F7208699B','1994','A course and reference for derived functors, spectral sequences and homological constructions. Start with concrete resolutions before the more specialized applications.','Rings, modules, chain complexes and basic category theory.',paid);
s('homological-algebra','Computational Homology','Tomasz Kaczynski, Konstantin Mischaikow and Marian Mrozek','Graduate','10.1007/b97315','2004','Studies effective homology computations and their mathematical foundations. A computational branch distinct from a general derived-category course.','Linear algebra, basic topology and chain complexes.');
add('category-theory','Basic Concepts of Enriched Category Theory','G. M. Kelly','Graduate','https://www.tac.mta.ca/tac/reprints/articles/10/tr10.pdf','1982 original; authorized TAC reprint 10, 2005','Develops enrichment, enriched limits and functor categories. Use examples enriched in abelian groups or topological spaces before general formalism.','Ordinary category theory; monoidal categories.',{source:'https://www.tac.mta.ca/tac/reprints/articles/10/tr10.html',kind:'Research monograph',access:'Direct open PDF',accessNote:'Authorized journal reprint of the complete monograph; observe the reprint terms.'});
add('category-theory','Sketches of an Elephant: A Topos Theory Compendium','Peter T. Johnstone','Research','https://academic.oup.com/book/52790','2002; compendium counted as one work','A substantial reference in topos theory, categorical logic and related structures. Choose a route through the compendium rather than treating it as a first category-theory text.','Category theory, sheaves and logic.',{...paid,kind:'Research monograph'});
s('category-theory','Categories and Sheaves','Masaki Kashiwara and Pierre Schapira','Research','10.1007/3-540-27950-4','2006','Links categorical limits, homological algebra and sheaf theory. A reference for derived sheaf methods after the basic categorical vocabulary.','Category theory, modules and homological algebra.');
s('harmonic-analysis','Fourier Integral Operators','J. J. Duistermaat','Research','10.1007/978-0-8176-8108-1','2011 reprint of earlier lecture text','Develops the operator and geometric language used in microlocal analysis. It is a specialist step beyond Fourier transforms and distributions.','Distributions; Fourier analysis; differential geometry.');
s('harmonic-analysis','A First Course in Harmonic Analysis','Anton Deitmar','Intermediate','10.1007/0-387-27561-4','Second edition, 2005','Moves from Fourier series and transforms toward harmonic analysis on groups. A lighter entry before measure-intensive general references.','Calculus, metric spaces and linear algebra.');
s('harmonic-analysis','Four Short Courses on Harmonic Analysis','Brigitte Forster and Peter Massopust (editors)','Graduate','10.1007/978-0-8176-4891-6','2010','A course collection on wavelets, frames and time-frequency methods. Distinguish the analytic foundations from its signal-processing applications.','Fourier analysis; Hilbert spaces.');
s('dynamics','Ergodic Theory and Dynamical Systems','Yves Coudène','Graduate','10.1007/978-1-4471-7287-1','2016','Develops ergodicity, mixing, entropy and hyperbolic examples. Use after measure theory, with concrete invariant-measure computations alongside abstract results.','Measure theory; real analysis.');
s('dynamics','Ergodic Theory, Hyperbolic Dynamics and Dimension Theory','Luis Barreira','Research','10.1007/978-3-642-28090-0','2012','Connects invariant measures, hyperbolic systems, thermodynamic formalism and fractal dimension. A specialist continuation of a first dynamics course.','Ergodic theory; smooth dynamics; measure theory.');
s('dynamics','Ergodic Theory','I. P. Cornfeld, S. V. Fomin and Ya. G. Sinai','Graduate','10.1007/978-1-4615-6927-5','English edition, 1982','A substantial classical treatment of measure-preserving dynamics and entropy. Read selectively with a modern course when notation or exposition differs.','Measure theory; basic functional analysis.');
s('symplectic-geometry','Hamiltonian Group Actions and Equivariant Cohomology','Shubham Dwivedi, Jonathan Herman, Lisa C. Jeffrey and Theo van den Hurk','Graduate','10.1007/978-3-030-27227-2','2019','Connects moment maps, reduction and equivariant cohomology. A branch into symmetry after the basic symplectic form and manifold constructions.','Differential forms; symplectic manifolds; algebraic topology.');
s('symplectic-geometry','Kuranishi Structures and Virtual Fundamental Chains','Kenji Fukaya, Yong-Geun Oh, Hiroshi Ohta and Kaoru Ono','Research','10.1007/978-981-15-5562-6','2020','A technical reference for virtual-chain constructions in holomorphic-curve theories. Different from Joyce’s Kuranishi-space approach; neither is a beginner’s first Floer course.','Symplectic topology, moduli of holomorphic curves and Fredholm analysis.');
s('point-set-topology','Topology','Klaus Jänich','Intermediate','9780387908922','English edition, 1984','A concise general-topology course with geometric examples. Use it to reinforce continuity, compactness and product constructions before manifold topology.','Sets, functions and proof-writing.');
s('point-set-topology','Metric Spaces','Satish Shirali and Harkrishan Lal Vasudeva','Intermediate','10.1007/1-84628-244-6','2006','Develops metric-space techniques linking real analysis and topology. Useful for practicing completeness, compactness and continuity with concrete examples.','Real-analysis basics; proof-writing.');
s('elementary-number-theory','Number Theory: An Introduction to Mathematics','W. A. Coppel','Intermediate','10.1007/978-0-387-89486-7','Second edition, 2009','Uses number theory as a meeting point of algebra, analysis and mathematical reasoning. A broader bridge beyond a first congruence course.','Proof-writing; elementary algebra.');
s('elementary-number-theory','Number Theory: Structures, Examples, and Problems','Dorin Andrica and Titu Andreescu','Intermediate','10.1007/b11856','2009','A problem-centered route through number-theoretic structures. Solve the examples actively before moving to local or analytic methods.','Elementary number theory; proof-writing.');
s('elementary-number-theory','Number Theory: An Introduction via the Distribution of Primes','Benjamin Fine and Gerhard Rosenberger','Intermediate','10.1007/978-3-319-43875-7','Second edition, 2016','Builds a bridge from elementary arithmetic to questions about prime distribution. Later analytic portions require stronger analysis preparation.','Elementary number theory; calculus and complex analysis for later material.');
s('algebraic-number-theory','Local Fields','Jean-Pierre Serre','Graduate','10.1007/978-1-4757-5673-9','English edition, 1979','Studies local fields, ramification and local class field theory through cohomological methods. Start after number fields and discrete valuations.','Algebraic number theory; Galois theory; group cohomology.');
s('algebraic-number-theory','Number Fields','Daniel A. Marcus','Graduate','10.1007/978-3-319-90233-3','Second edition, 2018','An algebra-first approach to rings of integers and ideal theory with many exercises. Suitable before a more local or adelic treatment.','Abstract algebra; field extensions.');
s('algebraic-number-theory','Number Theory','Helmut Hasse','Graduate','9783540427490','English edition, 1980; publisher reprint','A classical arithmetic reference connecting algebraic and local methods. Compare terminology with modern introductory number-field courses.','Graduate algebra; algebraic number theory.');
s('analytic-number-theory','Analytic Number Theory','Donald J. Newman','Graduate','10.1007/b98872','1998','A short course emphasizing efficient analytic arguments. Useful as a complement to a longer reference rather than an exhaustive survey of current methods.','Complex analysis; elementary number theory.');
s('analytic-number-theory','Problems in Analytic Number Theory','M. Ram Murty','Graduate','10.1007/978-0-387-72350-1','Second edition, 2008','A problem-driven course connecting analytic estimates and arithmetic. Use problems to develop technique instead of reading solutions passively.','Complex analysis; elementary number theory.');
s('modular-forms','Modular Forms: Basics and Beyond','Goro Shimura','Research','10.1007/978-1-4614-2125-2','2012','Develops modular forms, theta functions and half-integral weights. A specialized continuation after classical modular forms and complex analysis.','Modular forms; complex analysis; algebraic number theory.');
s('modular-forms','Automorphic Forms','Anton Deitmar','Graduate','10.1007/978-1-4471-4435-9','2012','An entry route to automorphic forms connecting analysis and representation-theoretic viewpoints. Compare its scope with a classical modular-form course.','Complex analysis; linear algebra; group theory.');
s('modular-forms','Modular Forms','Toshitsune Miyake','Graduate','10.1007/3-540-29593-3','English edition, 1989','A sustained classical modular-form reference. Read after the basic upper-half-plane and transformation-law examples.','Complex analysis; elementary number theory.');
s('calculus','A Course in Multivariable Calculus and Analysis','Sudhir R. Ghorpade and Balmohan V. Limaye','Intermediate','10.1007/978-1-4419-1621-1','2010','A rigorous multivariable course connecting calculus and analysis. Use it to move from computational recipes to proofs of differentiation and integration results.','Single-variable calculus and linear algebra.');
s('calculus','Multivariable Analysis','Satish Shirali and Harkrishan Lal Vasudeva','Intermediate','10.1007/978-0-85729-192-9','2011','A proof-based development of several-variable differentiation and integration with exercises. A bridge to manifold and measure-theoretic courses.','Real-analysis basics; linear algebra.');
s('calculus','Multivariable Calculus with Applications','Peter D. Lax and Maria Shea Terrell','Intermediate','10.1007/978-3-319-74073-7','2017','Connects theory with concrete applications in several variables. Study geometric and computational examples alongside a proof-focused analysis course.','Single-variable calculus; linear algebra.');
s('combinatorics','Extremal Combinatorics: With Applications in Computer Science','Stasys Jukna','Graduate','10.1007/978-3-642-17364-6','Second edition, 2011','Develops extremal arguments with links to computation. A route beyond elementary counting into structural bounds and probabilistic methods.','Discrete mathematics, proofs and elementary probability.');
s('measure-theory','Geometric Integration Theory','Steven G. Krantz and Harold R. Parks','Graduate','10.1007/978-0-8176-4679-0','2008','Studies integration over geometric sets, area/coarea ideas and related geometric measure tools. A specialist bridge from measure theory to geometric analysis.','Measure theory; multivariable analysis; differential geometry helpful.');

function tifr(topic,title,author,level,volume,note,prep){add(topic,title,author,level,'https://mathweb.tifr.res.in/Documents/Publications/Lectures/'+(volume===5?'05.pdf':'tifr'+String(volume).padStart(2,'0')+'.pdf'),'TIFR Lectures on Mathematics '+volume+'; authorized retypeset historical edition — original date on title page',note,prep,{kind:'Long lecture notes',source:'https://mathweb.tifr.res.in/lectures.html',access:'Direct open PDF',accessNote:'Complete institutional PDF, authorized for individual use only. Copyright remains with TIFR; retypesetting may retain errors. This is not a redistribution licence.'})}
tifr('abstract-algebra','Lectures on the Algebraic Theory of Fields','K. G. Ramanathan','Graduate',5,'A classical field-theoretic course for strengthening algebraic-extension and Galois arguments. Compare the historical presentation with a modern algebra text.','Abstract algebra; fields and polynomial rings.');
tifr('category-theory','Lectures on Sheaf Theory','C. H. Dowker','Graduate',6,'A sustained sheaf-theoretic course linking topology and homological methods. Useful for readers moving beyond categorical vocabulary to local-to-global constructions.','Topology; modules; homological algebra.');
tifr('representation-theory','Lectures on Lie Groups and Representations of Locally Compact Groups','François Bruhat','Graduate',14,'Links Lie-group structure with representation theory on locally compact groups. Develop integration and topological-group foundations before the specialized arguments.','Lie groups; measure theory; functional analysis.');
tifr('complex-analysis','Lectures on the Theory of Algebraic Functions of One Variable','Max Deuring','Graduate',18,'A classical algebraic-function course at the interface with Riemann surfaces. Algebraic viewpoint and historical notation differ from a first contour-integral course.','Complex analysis; field extensions; curves.');
tifr('commutative-algebra','Lectures on Unique Factorization Domains','Pierre Samuel','Graduate',30,'A focused study of factorization and commutative-ring structure. Useful for clarifying the distinction between elements, ideals and divisor-theoretic methods.','Commutative algebra; integral domains.');
tifr('commutative-algebra','Lectures on the Fourteenth Problem of Hilbert','Masayoshi Nagata','Research',31,'A specialist course on finite generation and invariant-ring phenomena. Read after Noetherian rings and examples in invariant theory.','Commutative algebra; invariant theory.');
tifr('homological-algebra','Lectures on Topics in Algebraic K-Theory','Hyman Bass','Research',41,'A classical route to algebraic K-theory from rings and projective modules. Compare with modern higher-K-theory references before using later categorical constructions.','Rings; projective modules; homological algebra.');
tifr('dynamics','Lectures on the Singularities of the Three-Body Problem','Carl Ludwig Siegel','Research',42,'A specialized course in celestial-mechanics dynamics and singularity analysis. This is a research branch, not a first qualitative ODE course.','ODE, mechanics, complex analysis and dynamical systems.');
tifr('point-set-topology','Lectures on Polyhedral Topology','John R. Stallings','Graduate',43,'A bridge from general topology into polyhedra and geometric topology. Use after basic compactness and quotient-space constructions.','General topology; simplicial ideas.');
tifr('algebraic-topology','Lectures on Introduction to Algebraic Topology','Georges de Rham','Graduate',44,'A classical topology course connecting geometric constructions with algebraic invariants. Compare conventions with a contemporary homology course.','General topology; groups and linear algebra.');
tifr('abstract-algebra','Lectures on Quadratic Jordan Algebras','Nathan Jacobson','Research',45,'A specialist introduction to nonassociative algebra and quadratic Jordan structures. Follow an ordinary ring-and-module course first.','Graduate algebra; nonassociative algebra foundations.');
tifr('differential-equations','Lectures on the Finite Element Method','Philippe G. Ciarlet','Graduate',49,'A numerical-PDE specialization with mathematical approximation foundations. Distinguish discretization theory from pure PDE existence and regularity.','Sobolev spaces; variational PDE; numerical linear algebra.');
tifr('functional-analysis','Lectures on Optimisation: Theory and Algorithms','Jean Céa','Graduate',53,'Connects variational analysis and optimization with algorithms. This is an applied branch of functional analysis, not a general Banach-space textbook.','Functional analysis; variational methods.');
tifr('commutative-algebra','Lectures on Expansion Techniques in Algebraic Geometry','Shreeram S. Abhyankar','Research',57,'An algebraic-geometry specialization emphasizing expansion techniques and local algebra. Use after commutative algebra and basic algebraic curves.','Local algebra; algebraic geometry.');
tifr('differential-geometry','Lectures on Torus Embeddings and Applications','Tadao Oda','Research',58,'A toric-geometry bridge connecting combinatorial cones and algebraic-geometric constructions. It complements, rather than replaces, a differential-geometric manifold course.','Algebraic geometry; lattices and convex cones.');
tifr('algebraic-number-theory','Lectures on Forms of Higher Degree','Jun-ichi Igusa','Research',59,'A specialized arithmetic course on higher-degree forms and related local questions. Study field and valuation foundations before its arithmetic constructions.','Algebraic number theory; local fields.');
tifr('commutative-algebra','Lectures on Equations Defining Space Curves','Lucien Szpiro','Research',62,'A specialist course connecting equations, ideals and the geometry of space curves. Use after graded commutative algebra and projective geometry.','Commutative algebra; algebraic curves; projective geometry.');
tifr('functional-analysis','Lectures on Numerical Methods for Non-Linear Variational Problems','Roland Glowinski','Research',65,'Develops variational formulations and computational methods for nonlinear problems. An applied specialization requiring analytic foundations.','Functional analysis; variational PDE; numerical analysis.');
tifr('representation-theory','Lectures on Representations of Complex Semi-simple Lie Groups','Thomas J. Enright','Research',66,'A specialist continuation from semisimple Lie algebras to representation-theoretic structure. Follow roots, weights and basic representations first.','Lie algebras; Lie groups; representation theory.');
tifr('differential-equations','Lectures on Three-Dimensional Elasticity','Philippe G. Ciarlet','Research',71,'A mathematical-elasticity course linking PDE and continuum models. Applied orientation is explicit; it is not a general first PDE course.','Sobolev spaces; variational calculus; mechanics.');
tifr('analytic-number-theory','Lectures on Sieve Methods and Prime Number Theory','Yoichi Motohashi','Research',72,'A specialist sieve-theoretic route into prime-distribution questions. Read after a first analytic-number-theory course.','Analytic number theory; elementary sieves; asymptotic estimates.');
tifr('probability','Lectures on Stochastic Control and Nonlinear Filtering','M. H. A. Davis','Research',75,'A stochastic-analysis branch connecting control and filtering. This is a specialized application, not an elementary probability course.','Stochastic processes; martingales; SDE.');
tifr('dynamics','Lectures on Topics in One-Parameter Bifurcation Problems','Patrick J. Rabier','Research',76,'A specialist course on how solutions change with a parameter. Functional-analytic preparation is needed beyond an elementary phase-plane course.','Functional analysis; nonlinear analysis; ODE/PDE.');
tifr('modular-forms','Lectures on Siegel Modular Forms and Representation by Quadratic Forms','Yoshiyuki Kitaoka','Research',77,'Connects Siegel modular forms and the arithmetic of quadratic forms. A higher-dimensional branch after classical modular forms.','Modular forms; quadratic forms; algebraic number theory.');
tifr('dynamics','Lectures on Numerical Methods in Bifurcation Problems','Herbert B. Keller','Graduate',79,'An applied computational route to bifurcation, complementing analytic dynamics. Numerical results require attention to approximation and stability.','ODE; numerical analysis; nonlinear equations.');
tifr('analytic-number-theory','Lectures on a Method in the Theory of Exponential Sums','Matti Jutila','Research',80,'A focused analytic-number-theory specialization in exponential-sum estimates. Enter after practicing analytic estimates and arithmetic sums.','Analytic number theory; Fourier methods; complex analysis.');
tifr('analytic-number-theory','Lectures on Mean Values of the Riemann Zeta Function','Aleksandar Ivić','Research',82,'A substantial specialist reference on zeta-function mean values. Read after Dirichlet series, analytic continuation and asymptotic methods.','Analytic number theory; complex analysis.');
tifr('analytic-number-theory','Lectures on the Mean-Value and Omega Theorems for the Riemann Zeta-Function','K. Ramachandra','Research',85,'Develops quantitative mean-value and omega-result techniques for the zeta function. A research continuation rather than a first introduction to primes.','Analytic number theory; zeta functions; complex-variable estimates.');
s('linear-algebra','Finite-Dimensional Vector Spaces','Paul R. Halmos','Intermediate','10.1007/978-1-4612-6387-6','Second edition, 1958; publisher reprint','A structural linear-algebra course emphasizing vector spaces and linear maps. A concise bridge beyond row reduction into invariant reasoning.','First linear algebra; proof-writing.');
add('linear-algebra','Numerical Linear Algebra','Lloyd N. Trefethen and David Bau','Graduate','https://epubs.siam.org/doi/book/10.1137/1.9781611977165','Twenty-fifth anniversary edition, 2022','Develops stable matrix computation, decompositions and iterative methods. Its numerical emphasis complements structural algebra; it does not replace proof-based linear algebra.','Linear algebra; norms; elementary numerical analysis.',paid);
add('linear-algebra','Topics in Matrix Analysis','Roger A. Horn and Charles R. Johnson','Graduate','https://www.cambridge.org/core/books/topics-in-matrix-analysis/B988495A235F1C3406EA484A2C477B03','First published 1991; consult publisher for reprint date','A separate companion to Matrix Analysis on numerical ranges, singular values, matrix equations and related topics. Chapters and reprints count as one work.','Advanced linear algebra and the basic matrix-analysis toolkit.',paid);
s('abstract-algebra','Algebra','Serge Lang','Graduate','10.1007/978-1-4613-0041-0','Revised third edition, 2002','A large structural algebra reference connecting groups, modules, fields and homological methods. Choose chapters around a course rather than reading every topic at once.','Undergraduate abstract algebra.');
s('abstract-algebra','Undergraduate Algebra','Serge Lang','Intermediate','10.1007/0-387-27475-8','Third edition, 2005','A first structural algebra course with groups, rings, fields and matrix groups. This is distinct from the graduate Algebra reference.','Linear algebra; proof-writing.');
s('set-theory','A Course on Borel Sets','Shashi Mohan Srivastava','Graduate','10.1007/b98956','1998','Develops Borel sets and measurable selections as a bridge to descriptive set theory. A different branch from forcing and large cardinals.','Topology; measure theory; set-theoretic language.');
s('model-theory','Finite Model Theory','Heinz-Dieter Ebbinghaus and Jörg Flum','Research','10.1007/3-540-28788-4','Second edition, 2005','Studies logical properties of finite structures and their computational connections. Compactness-based methods of ordinary model theory must not be transferred blindly to finite models.','First-order logic; model theory; discrete mathematics.');
add('model-theory','A Guide to NIP Theories','Pierre Simon','Research','https://www.cambridge.org/core/books/a-guide-to-nip-theories/C2105F093F7CE2CD0EB1C6E1BFBC76BF','2015','Introduces the non-independence property and its structural consequences. A specialist continuation after a first model-theory course, with links to combinatorics and geometry.','A first course in model theory; types and indiscernibles.',paid);
add('homological-algebra','Homological Algebra','Henri Cartan and Samuel Eilenberg','Graduate','https://www.jstor.org/stable/j.ctt1bpmb49','Original 1956; Princeton reprint 1999','A foundational classical reference for resolutions and derived functors. Historical exposition is useful alongside, rather than in place of, a modern course.','Graduate algebra; modules and complexes.',paid);
add('representation-theory','Representations and Characters of Groups','Gordon James and Martin Liebeck','Intermediate','https://www.cambridge.org/core/books/representations-and-characters-of-groups/9F525E6ACAC7FFADFDBDECE98C115F40','Publisher edition; consult source for edition / imprint','A concrete introduction to finite-group representations and character tables. A useful starting branch before Lie groups, modular representation theory or geometric representation theory.','Linear algebra; finite groups.',paid);
s('real-analysis','Real Mathematical Analysis','Charles C. Pugh','Intermediate','10.1007/978-3-319-17771-7','Second edition, 2015','A rigorous real-analysis course with geometric motivation, including several variables. Work through examples that distinguish intuition from valid limiting arguments.','Calculus; proofs; linear algebra.');
add('real-analysis','Real Analysis','Halsey L. Royden and Patrick M. Fitzpatrick','Graduate','https://www.pearson.com/en-us/subject-catalog/p/real-analysis/P200000007113','Fifth edition; released 2023, copyright 2024','A route from measure and integration into metric, topological and functional-analytic tools. It is more measure-intensive than an introductory sequences-and-series course.','Undergraduate real analysis; proof-writing.',paid);
s('measure-theory','Geometric Measure Theory','Herbert Federer','Research','10.1007/978-3-642-62010-2','Original 1969; publisher reprint','A substantial reference for geometric measure methods, rectifiability and currents. It requires strong analysis preparation and is not a first Lebesgue-integral textbook.','Measure theory; functional analysis; multivariable analysis.');
add('measure-theory','Measure and Integral: An Introduction to Real Analysis','Richard L. Wheeden and Antoni Zygmund','Graduate','https://www.routledge.com/Measure-and-Integral-An-Introduction-to-Real-Analysis/Wheeden-Zygmund/p/book/9781498702898','Second edition, 2015','Moves from Euclidean measure and integration toward abstract formulations and differentiation tools. The publisher catalogue corroborates the work; automated page access was refused.','Real analysis; multivariable calculus.',paid);
add('measure-theory','Measures, Integrals and Martingales','René L. Schilling','Graduate','https://www.cambridge.org/core/books/measures-integrals-and-martingales/7BEE19069C88A1376AEB988487D4131C','Original 2005; linked publisher edition — later 2017 edition also exists','Connects measure and integration with martingale methods and analytic applications. Versions count once; the linked edition’s own title page governs pagination.','Real analysis; elementary probability helpful.',paid);
add('measure-theory','Counterexamples in Measure and Integration','René L. Schilling and Franziska Kühn','Graduate','https://www.cambridge.org/core/books/counterexamples-in-measure-and-integration/043A4C16E3A2B3DD405770C302113932','2021','A companion for testing hypotheses and understanding failures of plausible integration statements. Use selectively alongside a systematic measure-theory course.','Measure theory and integration.',paid);
s('harmonic-analysis','Fourier Analysis and Nonlinear Partial Differential Equations','Hajer Bahouri, Jean-Yves Chemin and Raphaël Danchin','Research','10.1007/978-3-642-16830-7','2011','Develops Littlewood–Paley techniques and function spaces for nonlinear PDE. A research bridge after Fourier transforms, distributions and basic PDE.','Harmonic analysis; distributions; Sobolev spaces.');
add('harmonic-analysis','Fourier Analysis','Javier Duoandikoetxea','Graduate','https://www.ams.org/books/gsm/029/','English translation and revision by David Cruz-Uribe, 2001','A real-variable harmonic-analysis course on maximal operators, singular integrals and multipliers. The publisher’s downloadable preview is not the complete book.','Measure theory; functional analysis; Fourier transforms.',{...paid,previewUrl:'https://www.ams.org/bookstore/pspdf/gsm-29-prev.pdf',source:'https://www.ams.org/books/gsm/029/gsm029-endmatter.pdf'});
s('harmonic-analysis','From Fourier Analysis to Wavelets','Jonas Gomes and Luiz Velho','Graduate','10.1007/978-3-319-22075-8','2015','A focused course linking Fourier transforms with wavelets and multiresolution. Work reconstruction examples before treating wavelet machinery as a black box.','Fourier analysis; linear algebra; Hilbert spaces.');
add('point-set-topology','Introduction to Metric and Topological Spaces','Wilson A. Sutherland','Intermediate','https://academic.oup.com/book/54968','Second edition, 2009','Develops metric and general topological ideas with concrete examples. A bridge into abstract continuity, compactness and connectedness.','Proof-writing; sets and functions.',paid);
add('point-set-topology','General Topology','Stephen Willard','Graduate','https://store.doverpublications.com/products/9780486434797','Dover reprint, 2004; original 1970','An extensive general-topology reference for separation, compactness and convergence. Compare examples with an introductory course before using it as a reference.','A first point-set-topology course.',paid);
s('point-set-topology','Basic Topology 1: Metric Spaces and General Topology','Avishek Adhikari and Mahima Ranjan Adhikari','Intermediate','10.1007/978-981-16-6509-7','2022','Develops metric and general topology with motivations and exercises. Other volumes of the series are not silently counted as part of this linked book.','Proof-writing; metric-space examples.');
add('symplectic-geometry','Introduction to Symplectic and Hamiltonian Geometry','Ana Cannas da Silva','Graduate','https://people.math.ethz.ch/~acannas/Papers/impa.pdf','IMPA short course 2002; revised November 2007','A shorter course on symplectic structures and Hamiltonian geometry, distinct from the longer Lectures on Symplectic Geometry. Useful for orientation and selective review.','Smooth manifolds and differential forms.',{kind:'Long lecture notes',source:'https://people.math.ethz.ch/~acannas/',access:'Direct open PDF',accessNote:'Complete author-hosted course notes; reading access is not permission to redistribute.'});
s('symplectic-geometry','The Geometry of the Group of Symplectic Diffeomorphisms','Leonid Polterovich','Research','10.1007/978-3-0348-8299-6','2001','Studies the geometric structure of symplectic and Hamiltonian diffeomorphism groups. A specialist branch beyond a first symplectic course.','Symplectic geometry; Hamiltonian dynamics; Floer-theoretic background helpful.');
add('symplectic-geometry','Fukaya Categories and Picard–Lefschetz Theory','Paul Seidel','Research','https://ems.press/books/zlam/2','2008','Develops Fukaya categories and the invariants of Lagrangian submanifolds through Lefschetz-fibration methods. This is a technical research monograph, not a first category-theory course.','Symplectic topology; Floer theory; A-infinity algebra.',{...paid,kind:'Research monograph'});
s('symplectic-geometry','Symplectic Invariants and Hamiltonian Dynamics','Helmut Hofer and Eduard Zehnder','Research','10.1007/978-3-0348-0104-1','2011 reprint; original 1994','Connects capacities, rigidity, periodic orbits and symplectic fixed-point questions. Read after symplectic forms and Hamiltonian flows.','Symplectic geometry; variational methods; dynamical systems.');
s('symplectic-geometry','Introduction to Symplectic Geometry','Jean-Louis Koszul; translated by Yiming Zou','Graduate','10.1007/978-981-13-3987-5','English edition, 2019','A lecture-based development including symplectic group actions. Compare its conventions with modern differential-form treatments.','Differential geometry; Lie groups.');
s('elementary-number-theory','A Classical Introduction to Modern Number Theory','Kenneth Ireland and Michael Rosen','Intermediate','10.1007/978-1-4757-2103-4','Second edition, 1990','Bridges elementary arithmetic and modern algebraic number theory. Later topics require algebra beyond an introductory congruence course.','Elementary number theory; abstract algebra.');
add('elementary-number-theory','A Friendly Introduction to Number Theory','Joseph H. Silverman','Introductory','https://www.pearson.com/en-gb/subject-catalog/p/Silverman-Friendly-Introduction-to-Number-Theory-A-Pearson-New-International-Edition-4th-Edition/P200000005417','Fourth edition; international imprint 2014','A problem-and-example based introduction to number-theoretic reasoning. Freely available omitted chapters are supplements, not the full paid text.','School algebra; introductory proof-writing.',paid);
add('elementary-number-theory','Elementary Number Theory','Kenneth H. Rosen','Introductory','https://www.pearson.com/en-us/subject-catalog/p/elementary-number-theory/P200000007112/9780321974334','Seventh-edition current publisher listing; 2023 release / 2024 copyright','An introductory arithmetic course with algorithms and applications. Distinct from other authors’ books sharing this title.','School algebra; proof-writing.',paid);
s('dynamics','Ergodic Theory with a View towards Number Theory','Manfred Einsiedler and Thomas Ward','Graduate','10.1007/978-0-85729-021-2','2011','Develops measure-preserving dynamics with number-theoretic motivations. A bridge into homogeneous dynamics and equidistribution rather than a first ODE course.','Measure theory; functional analysis.');
add('combinatorics','Analytic Combinatorics','Philippe Flajolet and Robert Sedgewick','Graduate','https://algo.inria.fr/flajolet/Publications/book.pdf','2009','Connects generating functions with complex-analytic asymptotic methods. Use after elementary enumeration and a first complex-analysis course.','Combinatorics; generating functions; complex analysis.',{source:'https://algo.inria.fr/flajolet/Publications/AnaCombi/anacombi.html',access:'Direct open PDF',accessNote:'The author’s official book page explicitly offers the complete book PDF. Reading access does not authorize repository redistribution.'});
s('probability','Foundations of Modern Probability','Olav Kallenberg','Graduate','10.1007/978-3-030-61871-1','Third edition, 2021','A broad measure-theoretic probability reference spanning processes and advanced constructions. Use after an initial probability course, with selective reading guided by the intended topic.','Measure theory; probability; functional analysis helpful.');
add('abstract-algebra','A Course in Universal Algebra','Stanley Burris and H. P. Sankappanavar','Graduate','https://math.uwaterloo.ca/~snburris/htdocs/ualg.html','Original 1981; author-hosted online editions','Develops algebraic structures, varieties and logical connections beyond groups and rings. The author’s authorized download page includes revision information.','Abstract algebra; elementary logic.',{access:'Official page — verify access',accessNote:'The author explicitly provides an authorized electronic edition. This title opens its download/source page, not a direct PDF; follow its stated edition and terms.'});
